#!/usr/bin/env node
// Release bundler. Writes dist/, a self-contained folder that runs from
// file:// with no server:
//
//   dist/index.html   index.html with its module entry swapped for two
//                     classic <script> tags
//   dist/data.js      every record in the sharded data/ tree, assigned to
//                     window.LINEAGE_DATA
//   dist/app.js       every ES module the app imports, flattened into one
//                     classic script
//
// Why classic scripts: file:// origins apply CORS checks to module loads
// the same way they block fetch(), so neither the data nor the code can be
// an ES module in the release copy (A18 for the data, Q18 for the code).
// Development is untouched: tools/serve.js still serves the unbundled ES
// modules, and nothing in the source tree is rewritten.
//
// The code bundle is deliberately not a general bundler. Each module becomes
// a function scope in a small registry, run in dependency order, which is
// the same order ES module evaluation uses. It understands exactly the
// syntax this codebase uses (single-line named imports, and `export`
// before function, async function, and const) and fails loudly on anything
// else, so new syntax cannot slip through and quietly break the release.
//
// Stdlib only. Run: node tools/bundle.js (or npm run build)
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { join, dirname, posix } from 'node:path';
import { fileURLToPath } from 'node:url';
import { writeManifest, SHARD_TYPES } from './manifest.js';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const DATA_DIR = join(ROOT, 'data');
const DIST_DIR = join(ROOT, 'dist');
const ENTRY = 'main.js';
const ENTRY_TAG = `<script type="module" src="${ENTRY}"></script>`;

// ---- data --------------------------------------------------------------

function bundleData() {
  const manifest = writeManifest(DATA_DIR);
  const bundle = {};
  let count = 0;
  for (const shard of SHARD_TYPES) {
    bundle[shard] = {};
    for (const id of manifest[shard]) {
      bundle[shard][id] = JSON.parse(readFileSync(join(DATA_DIR, shard, `${id}.json`), 'utf8'));
      count++;
    }
  }
  return {
    source: `// Generated by tools/bundle.js. Do not edit by hand.\nwindow.LINEAGE_DATA = ${JSON.stringify(bundle, null, 2)};\n`,
    count,
  };
}

// ---- code --------------------------------------------------------------

const IMPORT_RE = /^import\s*\{([^}]*)\}\s*from\s*'([^']+)';?\s*$/;
const EXPORT_RE = /^export\s+(async\s+function|function|const)\s+([A-Za-z_$][\w$]*)/;

class BundleError extends Error {}

function transformModule(path, source) {
  const deps = [];
  const exported = [];
  const lines = source.split('\n').map((line, i) => {
    const where = `${path}:${i + 1}`;
    const imp = line.match(IMPORT_RE);
    if (imp) {
      const target = posix.normalize(posix.join(posix.dirname(path), imp[2]));
      deps.push(target);
      const bindings = imp[1]
        .split(',')
        .map((s) => s.trim())
        .filter(Boolean)
        .map((s) => {
          const [name, alias] = s.split(/\s+as\s+/);
          return alias ? `${name}: ${alias}` : name;
        });
      return `const { ${bindings.join(', ')} } = __modules[${JSON.stringify(target)}];`;
    }
    const exp = line.match(EXPORT_RE);
    if (exp) {
      exported.push(exp[2]);
      return line.replace(/^export\s+/, '');
    }
    if (/^\s*(import|export)\b/.test(line) || /\bimport\s*\(|import\.meta/.test(line)) {
      throw new BundleError(`${where}: module syntax tools/bundle.js does not handle: ${line.trim()}`);
    }
    return line;
  });
  return { deps, exported, body: lines.join('\n') };
}

// Depth-first from the entry, emitting each module after everything it
// imports: ES module evaluation order.
function bundleCode() {
  const order = [];
  const seen = new Map(); // path -> 'visiting' | transformed module
  function visit(path, from) {
    const state = seen.get(path);
    if (state === 'visiting') throw new BundleError(`import cycle through ${path} (from ${from})`);
    if (state) return;
    seen.set(path, 'visiting');
    let source;
    try {
      source = readFileSync(join(ROOT, path), 'utf8');
    } catch {
      throw new BundleError(`${from}: imports ${path}, which does not exist`);
    }
    const mod = transformModule(path, source);
    for (const dep of mod.deps) visit(dep, path);
    seen.set(path, mod);
    order.push([path, mod]);
  }
  visit(ENTRY, 'the entry point');

  const parts = order.map(
    ([path, mod]) =>
      `// ---- ${path} ----\n__modules[${JSON.stringify(path)}] = (() => {\n${mod.body}\nreturn { ${mod.exported.join(', ')} };\n})();\n`,
  );
  return {
    source: `// Generated by tools/bundle.js from the ES modules under ${ENTRY}. Do not edit by hand.\n(() => {\n'use strict';\nconst __modules = {};\n${parts.join('\n')}})();\n`,
    count: order.length,
  };
}

// ---- page --------------------------------------------------------------

function bundlePage() {
  const html = readFileSync(join(ROOT, 'index.html'), 'utf8');
  if (!html.includes(ENTRY_TAG)) {
    throw new BundleError(`index.html no longer contains ${ENTRY_TAG}; update tools/bundle.js to match`);
  }
  return html.replace(ENTRY_TAG, '<script src="data.js"></script>\n  <script src="app.js"></script>');
}

try {
  const data = bundleData();
  const code = bundleCode();
  const page = bundlePage();
  mkdirSync(DIST_DIR, { recursive: true });
  writeFileSync(join(DIST_DIR, 'data.js'), data.source);
  writeFileSync(join(DIST_DIR, 'app.js'), code.source);
  writeFileSync(join(DIST_DIR, 'index.html'), page);
  console.log(`Wrote ${DIST_DIR}/ (${data.count} records, ${code.count} modules). Open dist/index.html directly; no server needed.`);
} catch (err) {
  if (!(err instanceof BundleError)) throw err;
  console.error(`bundle failed: ${err.message}`);
  process.exit(1);
}
